async function m(r,c,s=100){const e=[];let n=1,i=Number.POSITIVE_INFINITY;for(;;){const a=new URLSearchParams(c);a.set("page",String(n)),a.set("page_size",String(s));const o=await fetch(`${r}?${a.toString()}`);if(!o.ok)throw new Error(`Failed to fetch paginated items from ${r}`);const t=await o.json(),l=Array.isArray(t.items)?t.items:[];if(e.push(...l),typeof t.total=="number"&&(i=t.total),l.length<s||e.length>=i)break;n+=1}return e}export{m as f};
